parameters.jsCode:
const DIAS_AVISO = 21;
const hoy = new Date();
hoy.setHours(0, 0, 0, 0);
const clientes = $input.all().map(i => i.json).filter(c => /^s/i.test(String(c['Activo'] || 's')));
const reg = c => String(c['Regimen'] || '');
const emp = c => /^s/i.test(String(c['Empleados'] || ''));
const tieneIVA = c => /directa|m[oó]dulos|limitada|^sl/i.test(reg(c));
const plazos = [];
const add = (cod, nom, mes, dia, tri, cond) => plazos.push({ cod, nom, mes, dia, tri, cond });
const T = [[4, 20, '1T'], [7, 20, '2T'], [10, 20, '3T'], [1, 20, '4T']];
for (const [mes, dia, tri] of T) {
  add('303', 'IVA · autoliquidación trimestral', mes, dia, tri, tieneIVA);
  add('130', 'IRPF · pago fraccionado (estimación directa)', mes, dia, tri, c => /directa/i.test(reg(c)));
  add('131', 'IRPF · pago fraccionado (módulos)', mes, dia, tri, c => /m[oó]dulos/i.test(reg(c)));
  add('111', 'Retenciones del trabajo · trimestral', mes, dia, tri, emp);
}
add('390', 'Resumen anual de IVA', 1, 30, 'anual', tieneIVA);
add('100', 'Declaración de la renta (IRPF)', 6, 30, 'anual', c => /directa/i.test(reg(c)));
add('190', 'Resumen anual de retenciones del trabajo', 1, 31, 'anual', emp);
add('347', 'Operaciones con terceros', 2, 28, 'anual', tieneIVA);
const avisos = [];
for (const c of clientes) {
  for (const p of plazos) {
    if (!p.cond(c)) continue;
    for (const y of [hoy.getFullYear(), hoy.getFullYear() + 1]) {
      const f = new Date(y, p.mes - 1, p.dia);
      const d = Math.round((f - hoy) / 86400000);
      if (d >= 0 && d <= DIAS_AVISO) {
        const fecha = String(f.getDate()).padStart(2, '0') + '/' + String(f.getMonth() + 1).padStart(2, '0');
        const cuando = d === 0 ? 'HOY' : d === 1 ? 'faltan 1 día' : 'faltan ' + d + ' días';
        const cliente = (c['Nombre'] || 'sin nombre') + (c['NIF'] ? ' (' + c['NIF'] + ')' : '');
        avisos.push({ f, linea: '• ' + fecha + ' · Modelo ' + p.cod + ' — ' + p.nom + ' — ' + cliente + ' — ' + cuando });
      }
    }
  }
}
if (avisos.length === 0) return [];
avisos.sort((a, b) => a.f - b.f);
const texto = avisos.map(a => a.linea).join('\n');
return [{ json: { total: avisos.length, texto: texto.slice(0, 3500) } }];

